INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerk immer nur eine Adressversion nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "IPv4 und IPv6 koexistieren"}, {"text": "Ja", "correct": false, "because": "Mehrere Versionen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Version nutzt 128-Bit-Adressen?', 3, '[{"text": "IPv6", "correct": true, "because": "Erweitert Adressraum"}, {"text": "IPv4", "correct": false, "because": "Nur 32-Bit"}, {"text": "IPv5", "correct": false, "because": "Nicht existent"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen hat ein Netzwerkprotokoll?', 5, '[{"text": "Adressierung", "correct": true, "because": "Identifiziert Geräte"}, {"text": "Routing", "correct": true, "because": "Leitet Daten"}, {"text": "Paketierung", "correct": true, "because": "Teilt Daten auf"}, {"text": "Grafikdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv4 hat 32-Bit-Adressen. b) IPv6 nutzt NAT.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IPv6 vermeidet NAT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk einrichte?', 4, '[{"text": "IP-Adressen", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerke"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IPv4-Adressen unendlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzter Adressraum"}, {"text": "Ja", "correct": false, "because": "Knappheit bekannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll hilft bei der Fehlerdiagnose?', 3, '[{"text": "ICMP", "correct": true, "because": "Zusammen mit IP genutzt"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet IPv6 gegenüber IPv4?', 5, '[{"text": "Größerer Adressraum", "correct": true, "because": "128-Bit vs. 32-Bit"}, {"text": "Kein NAT nötig", "correct": true, "because": "Direkte Adressierung"}, {"text": "Autokonfiguration", "correct": true, "because": "Einfachere Einrichtung"}, {"text": "Kleinere Pakete", "correct": false, "because": "Nicht zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) IPv4 noch weit verbreitet ist und b) IPv6 keine Subnetze unterstützt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IPv6 unterstützt Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Netzwerkprotokoll zu nutzen?', 4, '[{"text": "IP-Adressen", "correct": false, "because": "Identifizieren Geräte"}, {"text": "Routing-Tabelle", "correct": false, "because": "Leitet Daten"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist IPv6 rückwärtskompatibel zu IPv4?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Formate"}, {"text": "Ja", "correct": false, "because": "Adapter nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken nutze ich für IP-Adressierung?', 4, '[{"text": "Subnetting", "correct": true, "because": "Teilt Netzwerke"}, {"text": "DHCP", "correct": true, "because": "Automatische Zuweisung"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IP-Adressen nur für Computer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für IoT, Router"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Netzwerkprotokoll?', 3, '[{"text": "Datenübertragung", "correct": true, "because": "Verbindet Geräte"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv4 nutzt NAT. b) IPv6 ist langsamer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IPv6 nicht langsamer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Subnetzmaske?', 4, '[{"text": "Netzwerk trennen", "correct": true, "because": "Definiert Bereiche"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob IP-Adressen statisch sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamisch möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Netzwerkprotokoll nützlich?', 5, '[{"text": "Adresszuweisung", "correct": true, "because": "Identifiziert Geräte"}, {"text": "Routing", "correct": true, "because": "Leitet Daten"}, {"text": "Paketverwaltung", "correct": true, "because": "Strukturiert Übertragung"}, {"text": "Grafikdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt IPv6 NAT wie IPv4?', 3, '[{"text": "Nein", "correct": true, "because": "Direkte Adressierung"}, {"text": "Ja", "correct": false, "because": "IPv6 vermeidet NAT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Netzwerkprotokoll?', 4, '[{"text": "Daten zwischen Servern senden", "correct": true, "because": "IP-Anwendung"}, {"text": "Webdesign erstellen", "correct": false, "because": "Anderer Bereich"}, {"text": "Daten komprimieren", "correct": false, "because": "Anderer Zweck"}]');
